        long N = Long.parseLong(line.trim());
        long sumExp = N * (N + 1) / 2;
        long sqExp = N * (N + 1) * (2 * N + 1) / 6;
        long sumAct = 0, sqAct = 0;
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            long v = Long.parseLong(st.nextToken());
            sumAct += v;
            sqAct += v * v;
        }
        long diff = sumAct - sumExp;
        long sqDiff = sqAct - sqExp;
        long plus = sqDiff / diff;
        long R = (diff + plus) / 2;
        long M = plus - R;
        System.out.println(R + " " + M);
    }
}

