            counts.put(v, counts.getOrDefault(v, 0) + 1);
        }
        boolean found = false;
        if (D == 0) {
            for (int c : counts.values()) if (c > 1) { found = true; break; }
        } else {
            for (long x : counts.keySet()) if (counts.containsKey(x + D)) { found = true; break; }
        }
        System.out.println(found ? "PAIR_FOUND" : "NO_PAIR");
    }
}

