def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N, T = int(input_data[0]), int(input_data[1])
    a = sorted([int(x) for x in input_data[2:2+N]])
    res = []
    for i in range(N - 3):
        if i > 0 and a[i] == a[i - 1]: continue
        for j in range(i + 1, N - 2):
            if j > i + 1 and a[j] == a[j - 1]: continue
            l, r = j + 1, N - 1
            rem = T - a[i] - a[j]
            while l < r:
                s = a[l] + a[r]
                if s == rem:
                    res.append(f'{a[i]} {a[j]} {a[l]} {a[r]}')
                    while l < r and a[l] == a[l + 1]: l += 1
                    while l < r and a[r] == a[r - 1]: r -= 1
                    l += 1; r -= 1
                elif s < rem:
                    l += 1
                else:
                    r -= 1
    if not res:
        print('NONE')
    else:
        for q in res:
            print(q)

