        for (int i = 0; i < N - 3; i++) {
            if (i > 0 && a[i] == a[i - 1]) continue;
            for (int j = i + 1; j < N - 2; j++) {
                if (j > i + 1 && a[j] == a[j - 1]) continue;
                int l = j + 1, r = N - 1;
                long rem = T - a[i] - a[j];
                while (l < r) {
                    long s = a[l] + a[r];
                    if (s == rem) {
                        res.add(a[i] + " " + a[j] + " " + a[l] + " " + a[r]);
                        while (l < r && a[l] == a[l + 1]) l++;
                        while (l < r && a[r] == a[r - 1]) r--;
                        l++; r--;
                    } else if (s < rem) l++;
                    else r--;
                }
            }
        }
        if (res.isEmpty()) System.out.println("NONE");
        else for (String q : res) System.out.println(q);
