    static long[] mergeSort(long[] arr, int l, int r) {
        if (l >= r) return new long[]{arr[l]};
        int mid = (l + r) / 2;
        long[] L = mergeSort(arr, l, mid);
        long[] R = mergeSort(arr, mid+1, r);
        long[] res = new long[L.length + R.length];
        int i = 0, j = 0, k = 0;
