            if (L[i] <= R[j]) res[k++] = L[i++];
            else { res[k++] = R[j++]; count += L.length - i; }
        }
        while (i < L.length) res[k++] = L[i++];
        while (j < R.length) res[k++] = R[j++];
        return res;
    }
