using namespace std;

long long merge_count(vector<long long>& arr, int l, int r) {
    if (l >= r) return 0;
    int mid = (l + r) / 2;
    long long inv = merge_count(arr, l, mid) + merge_count(arr, mid+1, r);
    vector<long long> tmp;
    int i = l, j = mid+1;
    while (i <= mid && j <= r) {
        if (arr[i] <= arr[j]) tmp.push_back(arr[i++]);
        else { tmp.push_back(arr[j++]); inv += mid - i + 1; }
    }
    while (i <= mid) tmp.push_back(arr[i++]);
    while (j <= r) tmp.push_back(arr[j++]);
    for (int k = l; k <= r; k++) arr[k] = tmp[k-l];
    return inv;
}

int main() {
    int N; if (!(cin >> N)) return 0;
    vector<long long> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];
    cout << merge_count(a, 0, N-1) << '\n'; return 0;
}

