public class Main {
    static Random rand = new Random();
    static long quickselect(long[] a, int lo, int hi, int k) {
        if (lo == hi) return a[lo];
        int pivIdx = lo + rand.nextInt(hi - lo + 1);
        long piv = a[pivIdx]; a[pivIdx] = a[hi]; a[hi] = piv;
        int p = lo;
        for (int i = lo; i < hi; i++) if (a[i] <= piv) { long t = a[p]; a[p] = a[i]; a[i] = t; p++; }
        long t = a[p]; a[p] = a[hi]; a[hi] = t;
        if (k == p) return a[p];
        else if (k < p) return quickselect(a, lo, p-1, k);
        else return quickselect(a, p+1, hi, k);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
