        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) { P[i] = Long.parseLong(st.nextToken()); lo = Math.max(lo, P[i]); hi += P[i]; }
        long ans = hi;
        while (lo <= hi) { long mid = (lo + hi) / 2; if (feasible(P, K, mid)) { ans = mid; hi = mid - 1; } else lo = mid + 1; }
        System.out.println(ans);
    }
}

