import java.io.*;
import java.util.*;

public class Main {
    static void generateSums(long[] arr, int idx, long current, List<Long> list) {
        if (idx == arr.length) { list.add(current); return; }
        generateSums(arr, idx + 1, current, list);
        generateSums(arr, idx + 1, current + arr[idx], list);
    }
    static int lowerBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) / 2;
            if (arr[m] >= target) r = m; else l = m + 1;
        }
        return l;
    }
    static int upperBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) / 2;
            if (arr[m] > target) r = m; else l = m + 1;
        }
        return l;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        StringTokenizer st = new StringTokenizer(line);
        int N = Integer.parseInt(st.nextToken());
        long A = Long.parseLong(st.nextToken()), B = Long.parseLong(st.nextToken());
        long[] nums = new long[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) nums[i] = Long.parseLong(st.nextToken());

        int mid = N / 2;
        long[] left = Arrays.copyOfRange(nums, 0, mid);
        long[] right = Arrays.copyOfRange(nums, mid, N);
        List<Long> l1 = new ArrayList<>(), l2 = new ArrayList<>();
        generateSums(left, 0, 0, l1);
        generateSums(right, 0, 0, l2);
        long[] rSums = new long[l2.size()];
        for (int i = 0; i < l2.size(); i++) rSums[i] = l2.get(i);
        Arrays.sort(rSums);

        long count = 0;
        for (long ls : l1) {
            int idx1 = lowerBound(rSums, A - ls);
            int idx2 = upperBound(rSums, B - ls);
            count += (idx2 - idx1);
        }
        System.out.println(count);
    }
}

